// AppConfig defines model for AppConfig.
type AppConfig struct {
	// Legal 이용약관·개인정보 처리방침 정적 페이지의 절대 주소입니다(D80). app은 주소를 상수로 두지 않고 이 값을 씁니다.
	// 주소에는 query가 없고, app이 화면 언어로 `?lang=ko|en|ja`를 붙여 엽니다.
	// 페이지(`GET /legal/terms`·`GET /legal/privacy`)는 `/v1` 밖 정적 HTML이라 이 명세의 operation이 아닙니다.
	// `lang`이 없거나 모르는 값이면 기본 언어 `en`이고, 그 언어의 원문이 아직 없으면 404와 준비 중 안내 페이지입니다(다른 언어로 대신하지 않음).
	Legal LegalLinks `json:"legal"`

	// MinimumVersion 플랫폼별 최소 앱 버전(semver 문자열)
	MinimumVersion MinimumVersion `json:"minimumVersion"`
}

